# Guião final V3g em dados: cada fala com marcas de emoção por frase (mais exageradas), velocidade, intervalo, plano e efeitos.
# gap: segundos após o fim da fala anterior (negativo = por cima). shot: AP | WIDE | PM | CU. react: planos de reação depois da fala.
L = []; MARK = []
def line(i, ch, text, speed=1.0, gap=0.35, shot=None, react=(), sfx=(), vol=0.0, shout=False): L.append(dict(id=i, ch=ch, text=text, speed=speed, gap=gap, shot=shot, react=list(react), sfx=list(sfx), vol=vol, shout=shout))
def mark(name, gap=0.0, dur=0.0): L.append(dict(id='@'+name, ch=None, gap=gap, dur=dur))
mark('title', 0.3, 3.8)
line('a01','ap',"[warm, grandiose, booming TV host, over-the-top] Boa noite, Famalicão! Bem-vindos aos cinquenta anos da JSD e a um programa que se chama… [pause, dramatic whisper] Quem é que disse isto?",1.08,0.4,'AP')
line('a02','ap',"[fast, confiding, excited] O formato é simples. Eu leio uma frase. [teasing] Quatro convidados explicam, com enorme elegância, que não foram eles. [gleeful] Depois acusam-se uns aos outros. [warm] E no fim, vocês, aí sentados, votam no telemóvel.",1.12,0.25,'AP')
line('a03','ap',"[deadpan, bone dry] O que é, para um jantar de partido, o mais próximo de uma eleição interna sem ninguém a gritar.",0.95,0.3,'AP')
line('a04','ap',"[smug, relishing] O prémio é nenhum. [pause] [wicked grin] O castigo é pagar a próxima ronda.",1.0,0.8,'AP')
line('a05','ap',"[conspiratorial, stage whisper] Quero cumprimentar a mesa dos dirigentes, que está, como sempre, mais perto da comida. [teasing, mock-innocent] E a mesa do fundo, onde ninguém sabe se estamos num jantar ou numa reunião de distrital.",1.05,0.6,'AP')
line('a06','ap',"[formal, pompous, then amused] Os convidados. O Professor Cavaco Silva: dedica cinco minutos de manhã e cinco minutos à tarde a ler os jornais. [pause] [wry, delighted] Tem um cronómetro. Tem um cronómetro para o cronómetro.",1.05,0.6,'AP')
line('a07','cav',"[proud, smug, pompous] Exato.",0.9,0.35,'PM')
line('a08','ap',"[mock-solemn, theatrical] Pedro Passos Coelho. Responde a tudo. [pause] Em diferido. [pause] Muito diferido.",0.95,0.5,'AP')
mark('sil_pas1', 0.0, 5.5)
line('a09','pas',"[flat, very slow, deadpan, half asleep] Boa noite.",0.8,0.2,'PM',react=[('AP','neutro',0.5)])
line('a10','ap',"[admiring, ironic, grandiose] Paulo Portas. Um orador de tal calibre que, se lhe dessem uma frase curta, pedia desculpa à frase.",1.05,0.5,'AP')
line('a11','por',"[grandiose, proud, bursting with pride] Com anexos!",1.0,0.2,'PM')
line('a12','ap',"[wry, knowing, winking] E Luís Montenegro. Convencido de que não há problema que uma reunião não resolva. [pause] [dry] E que não há reunião que não crie um problema.",1.05,0.5,'AP')
line('a13','mon',"[eager, rushing, breathless] Proponho um ponto prévio!",1.15,0.15,'PM')
line('a14','ap',"[dry, flat, deadpan] Ainda nem se sentou.",0.95,0.2,'AP',react=[('montenegro','surpresa',0.8)])
line('b01','ap',"[solemn, tearful, melodramatic, trembling voice] Ouçam. E comovam-se. Se algum dia tiver de perder umas eleições em Portugal para salvar o país, que se lixem as eleições. O que interessa é Portugal.",0.95,0.7,'AP',sfx=[('sting',0)])
line('b02','ap',"[sniffling, wiping tears] Lindo. [deadpan, flat] Isto é poesia. Uma poesia que só falha em dois aspetos: [pause] na rima, [pause] e na decência.",1.0,0.5,'AP',react=[('cavaco','calase',0.8),('portas','ironico',0.8)])
line('b03','ap',"[teasing, mischievous] Umas eleições. Como quem perde umas meias. [smug, boasting] Ora eu perco meias há trinta anos. Eleições, nunca perdi nenhuma: nunca me candidatei. [dry, deadpan] Isto não é gabarolice. É estratégia.",1.05,0.6,'AP')
line('c01','ap',"[formal, stern, newsreader] Primeira pergunta, ao Professor. Foi o senhor que disse isto? [pause] Sim ou não.",1.0,0.5,'AP')
line('c02','cav',"[pompous, lecturing, accelerating, grand] Antes de mais, o que é «não»? Do latim «non»: nem. E «sim», do latim «sic»: assim. Ora, «assim» e «nem», na sua origem indo-europeia…",1.12,0.3,'PM')
line('c03','por',"[irritated, cutting, sarcastic] Professor, isto é uma aula ou uma resposta?",1.1,-0.35,'WIDE')
line('c04','cav',"[offended, haughty, outraged] Convém distinguir!",1.0,0.1,'PM',sfx=[('buzz',1.4)])
line('c05','ap',"[stern, shouting, authoritative] TEMPO!",1.0,0.1,'AP',shout=True,vol=3)
line('c06','cav',"[defensive, quick, flustered] Dedico cinco minutos de manhã e cinco minutos à tarde a ler os jornais.",1.1,0.4,'PM')
line('c07','ap',"[dry, deadpan] Isso não responde a nada.",0.95,0.2,'AP')
line('c08','cav',"[indignant, shouting, wounded pride] Responde ao horário!",1.0,0.1,'CU',shout=True,vol=3)
line('c09','ap',"[formal, bored] Dr. Portas. Sim ou não.",1.0,0.5,'AP')
line('c10','por',"[theatrical, fast, grandiose, climbing] Meu caro apresentador, minhas senhoras e meus senhores, ilustres membros da mesa dos dirigentes e distintos clientes do bar aberto, tendo em conta o que, no seguimento do que, e não obstante o que, a propósito de tudo quanto, e é por tudo isto, e muito mais que a falta de tempo me impede de enumerar, que a minha resposta é, sem margem para equívocos… [long pause] [flat, tiny, anticlimax] não.",1.28,0.3,'PM',sfx=[('buzz',9.0),('buzz',13.0),('buzz',17.0)])
line('c11','mon',"[urgent, scandalised, appalled] Proponho uma reunião para decidir quando é que o Dr. Portas acaba!",1.15,-0.25,'WIDE')
line('c12','por',"[outraged, shocked] Estou a meio!",1.1,0.1,'PM')
line('c13','mon',"[hysterical, shouting, losing control] ESTAMOS TODOS A MEIO!",1.0,0.1,'CU',shout=True,vol=3)
line('c14','ap',"[exasperated, weary, defeated] Foram quarenta segundos. [pause] Para uma sílaba.",0.95,0.5,'AP')
line('c15','ap',"[formal] Dr. Montenegro. Sim ou não?",1.0,0.5,'AP')
line('c16','mon',"[calm, institutional, reasonable] Não é não! [pause] [rising, tense] ESTOU CALMO!",1.1,0.3,'PM',shout=True)
line('c17','mon',"[screaming, hysterical, cracking voice] É A CALMAR!",1.0,0.2,'CU',shout=True,vol=4)
line('c18','ap',"[amused, drawn-out] Dr. Passos.",0.9,0.5,'AP')
mark('sil_pas2', 0.0, 6.0)
line('c19','ap',"[teasing, whispering] Dr. Passos, está connosco?",0.95,0.2,'AP')
line('c20','pas',"[flat, very slow, deadpan] Estou. [long pause] Para futuro.",0.8,0.4,'PM')
line('c21','ap',"[resigned, sighing] Voltaremos ao Dr. Passos em dois mil e trinta e um.",1.0,0.5,'AP')
line('d01','cav',"[prosecutorial, cold, pointing] O Dr. Portas é suspeito. A frase tem um verbo no conjuntivo, bem usado: «tiver de perder». [pause] Só um orador faria isto.",1.0,0.8,'WIDE')
line('d02','por',"[flattered, preening, then outraged] Obrigado! [pause] [gasp, shouting] Não, espere: isso é uma acusação!",1.15,0.3,'PM')
line('d03','cav',"[smug, superior] Convém distinguir. Foi um facto.",0.95,0.2,'PM')
line('d04','mon',"[eager, accusing, pointing] Foi ele! Tem uma defesa de quarenta segundos para uma frase de vinte palavras!",1.2,0.2,'WIDE')
line('d05','por',"[disdainful, sneering] A sua defesa é uma ata sobre uma ata!",1.15,-0.1,'PM')
line('d06','mon',"[hurt, whining, shouting] A ata foi aprovada!",1.05,0.1,'CU',shout=True)
line('d07','por',"[sly, triumphant, mocking] O Dr. Montenegro, perante qualquer frase, propõe uma reunião. Esta frase não propõe nenhuma reunião. [pause] Logo, não é dele!",1.12,0.3,'PM')
line('d08','mon',"[offended, rising, indignant] Isso é um insulto! Eu consigo dizer uma frase sem reunião! Ouçam: [solemn, breathing in] Que se… [panicked, shouting] Antes de dizer, proponho uma reunião para decidir se digo!",1.12,0.3,'PM',shout=True)
line('d09','ap',"[delighted, gleeful] Prova concluída.",1.0,0.3,'AP',react=[('montenegro','surpresa',0.7)])
line('d10','mon',"[snide, sneering] E o Passos nunca diria esta frase: demoraria tanto a dizê-la que a eleição já tinha acontecido.",1.12,0.5,'WIDE')
mark('sil_pas3', 0.0, 5.0)
line('d11','pas',"[flat, slow, deadpan] Isso fica para futuro.",0.8,0.3,'PM')
line('d12','cav',"[alarmed, scandalised, shouting] Isso é o que um culpado diria!",1.1,0.15,'WIDE',shout=True,vol=2)
line('d13','pas',"[deadpan, slow] O Professor. [long pause] Porque a frase tem um verbo bem usado, e ninguém mais o usa.",0.8,0.5,'PM')
line('d14','cav',"[proud, then horrified] Obrigado! [pause] [panicked] Espere…",1.05,0.3,'PM')
line('d15','por',"[theatrical, accusing, thunderous] O Professor cronometra tudo! A frase tem vinte e uma palavras. Contou-as!",1.2,0.3,'WIDE',shout=True)
line('d16','cav',"[outraged, shouting, defensive] Foram vinte e duas!",1.0,0.1,'CU',shout=True,vol=3)
line('d17','mon',"[gasping, scandalised] AH!",1.0,0.0,'WIDE',shout=True,vol=2)
line('d18','ap',"[triumphant, booming] O Professor sabe quantas são! [pause] [mock-judicial] Foi o Professor.",1.0,0.3,'AP')
line('d19','cav',"[panicked, squeaking] Eu conto tudo!",1.0,0.2,'CU',shout=True)
line('d20','cav',"[shouting, furious] Foi o Portas, que objeta antes!",1.15,0.7,'WIDE',shout=True,vol=2)
line('d21','por',"[shouting, furious] Foi o Montenegro, que propõe comissões!",1.2,-0.4,'WIDE',shout=True,vol=2)
line('d22','mon',"[shouting, hysterical] Foi o Passos, que adia tudo!",1.2,-0.4,'WIDE',shout=True,vol=2)
