line('d23','pas',"[flat, calm, deadpan] …Foi o Professor.",0.8,0.2,'PM')
line('d24','ap',"[delighted, rubbing hands] A discussão está ótima!",1.05,0.4,'AP')
line('e01','ap',"[mischievous, gleeful] Cada um lê a frase. Em voz alta. À vez. [stage whisper to the room] Acho que vai correr bem.",1.05,0.6,'AP')
line('e02','cav',"[pompous, grand] Se, em qualquer momento ulterior, vier a verificar-se a necessidade de perder o sufrágio…",1.0,0.4,'PM')
line('e03','por',"[sneering, scornful] Isso não é uma frase. É um requerimento.",1.1,0.1,'WIDE')
line('e04','por',"[grandiose, rushing, tangled] Se, porventura, e não obstante o que, em tempo útil, algum dia, fosse a perder umas… [pause] [mumbling] lixarem-se.",1.2,0.8,'PM')
line('e05','mon',"[sarcastic, scoffing] Chamou «lixarem-se» a um anexo?",1.1,0.1,'WIDE')
line('e06','mon',"[confident, then anxious] Proponho uma reunião para perder umas eleições.",1.1,0.7,'PM')
line('e07','cav',"[disgusted, withering] Isso não tem verbo.",0.95,0.1,'WIDE')
mark('sil_pas5', 0.1, 4.0)
line('e08','pas',"[flat, dead slow] Se algum dia… [very long pause] …isso fica para futuro.",0.75,0.2,'PM')
line('e09','cav',"[exasperated, shouting] ISSO NÃO É A FRASE!",1.0,0.0,'WIDE',shout=True,vol=3)
line('e10','por',"[exasperated, shouting] ISSO NÃO É A FRASE!",1.1,-0.5,'WIDE',shout=True,vol=3)
line('e11','mon',"[exasperated, shouting] ISSO NÃO É A FRASE!",1.1,-0.5,'WIDE',shout=True,vol=3)
line('e12','ap',"[deadpan, wry] Os quatro tentaram. Os quatro falharam. Ou seja: ninguém consegue dizê-la. [pause] [knowing wink] Logo, foi outro. Ou o fantasma de um deputado.",1.0,0.8,'AP')
line('f01','ap',"[excited, teasing] Mas calma, que a resposta chega no fim. O Dr. Passos tinha ficado de responder à primeira pergunta. [pause] Vamos ouvi-lo.",1.08,0.6,'AP')
mark('sil_pas6', 0.0, 6.0)
